// A terminal shows each command's output and errors in order, and scrolls like a real
// one: every frame shows the newest lines.
// A terminal recording also writes frames/transcript.md: the caption, the command and
// the output of each step, as its frame shows them. The specification packet carries
// this transcript in place of the frames, because the frames of a terminal are text.

const lines = [];
const transcript = [];
const problems = [];

if (script.kind === "terminal") {
  const entries = transcript.map((t) =>
    `## Frame ${String(t.n).padStart(2, "0")} · ${t.caption}\n\n\`\`\`\`\n$ ${t.run}\n${t.out}\n\`\`\`\`\n`);
  fs.writeFileSync(path.join(outDir, "frames", "transcript.md"),
    `# Transcript of the frames · ${script.title || ""}\n\n` +
    "Each entry is one frame: its caption, the command of its step, and what the command printed.\n\n" +
    entries.join("\n"));
}

if (problems.length) {
  for (const problem of problems) console.error(`record_gif: ${problem}`);

